// Package buffstat is the single table of v145 temporary (buff) stats: which
// bit of the 8×U32 SecondaryStat mask each stat uses and how the native client
// decodes it locally (CWvsContext::OnTemporaryStatSet0x939817 ->
// encodeForLocal0x6C4EF8) and for other users (0x8B3F35 ->
// encodeForRemote0x6AFDAB).
//
// The table is generated by tools/gen-buffstat.py from the IDA audit in
// Open-Maple docs/server/baseline/buffstat-native.json and is owned by the S0a skill-core
// thread. Job threads refer to stats by name and never encode masks
// themselves; a missing stat is requested from S0a with Java and IDA evidence
// (Open-Maple docs/server/SKILLS-PARALLEL-PLAN.md section 4).
//
// Stats are persisted by Name, never by bit, so a corrected bit needs no data
// migration. Names come from Java buffstatus.properties and are semantics
// only: the wire layout is native, the meaning of a bit still needs MCP proof
// for each skill that uses it.
package buffstat

import (
	"fmt"
	"sort"
)

// Stat is the Java MapleBuffStatus name, e.g. "MAXHP".
type Stat string

// MaskWords is the number of U32 words in the v145 SecondaryStat mask.
const MaskWords = 8

// Value is one field the client reads.
type Value uint8

const (
	ValueU8 Value = iota + 1
	ValueI16
	ValueI32
	// ValueI32x22 is the fixed 22-entry I32 array read for bit 114.
	ValueI32x22
)

// TwoStateKind is the native class of a two-state stat. Every kind starts
// with value I32, reason I32 and last-updated (sign U8 + delta I32).
type TwoStateKind uint8

const (
	// TwoStateTerm adds a U16 term in seconds (energy charge, dash).
	TwoStateTerm TwoStateKind = iota + 1
	// TwoStateNoExpire adds nothing (monster riding); the server cancels it.
	TwoStateNoExpire
	// TwoStateBooster adds a time (sign U8 + delta I32) and a U16 term
	// (speed infusion).
	TwoStateBooster
	// TwoStateGuided adds two I32 (homing beacon target).
	TwoStateGuided
)

// Spec is one row of the table.
type Spec struct {
	Name    Stat
	Aliases []Stat
	// Bit is 0..255. The bit lives in mask word 7-Bit/32 at 1<<(Bit%32)
	// (word 0 is sent first), the same layout as Java MapleBuffStatus.
	Bit int
	// Order is the 1-based position in encodeForLocal's triplet section:
	// value (I16, or I32 when any ForcesInt stat is in the mask), source I32,
	// duration I32. Zero means the stat has no triplet.
	Order int
	// Tail is read after the triplets and the three unconditional bytes, in
	// TailOrder. Stats sharing a TailOrder share one read (the client tests
	// a composite flag).
	TailOrder int
	Tail      []Value
	// TwoState is the TwoStateTemporaryStat layout of bits 248..255, read
	// after the tails in bit order, locally and remotely.
	TwoState TwoStateKind
	// IndieOrder is the 1-based position in the indie (stacked) section read
	// by IndieTempStat::Decode after the two-state stats; remote clients
	// ignore indie stats.
	IndieOrder int
	// RemoteOrder is the 1-based position in encodeForRemote; Remote is the
	// payload read there (possibly empty). Zero means other users' clients
	// ignore the bit.
	RemoteOrder int
	Remote      []Value
	// ForcesInt marks the stats whose presence makes isEncodeInt0x6A66BD
	// switch every local triplet value in the packet to I32.
	ForcesInt bool
	// MoveTail marks stats for which OnTemporaryStatSet reads one movement
	// byte after the delay field (predicate 0x6AD699).
	MoveTail bool
	// Verified names the native evidence for the layout. Empty means the row
	// only exists in Java (or its native layout is not audited) and it must
	// not be sent to a client.
	Verified string
}

// LocalSendable reports whether the stat may appear in a local (0x2A) packet.
func (s Spec) LocalSendable() bool {
	return s.Verified != "" && (s.Order > 0 || s.TailOrder > 0 || s.TwoState != 0 || s.IndieOrder > 0)
}

var byName = map[Stat]Spec{}
var byBit = map[int]Spec{}

func init() {
	for _, s := range table {
		if s.Bit < 0 || s.Bit >= MaskWords*32 {
			panic(fmt.Sprintf("buffstat: %s bit %d out of range", s.Name, s.Bit))
		}
		if _, dup := byBit[s.Bit]; dup {
			panic(fmt.Sprintf("buffstat: duplicate bit %d", s.Bit))
		}
		byBit[s.Bit] = s
		for _, n := range append([]Stat{s.Name}, s.Aliases...) {
			if _, dup := byName[n]; dup {
				panic(fmt.Sprintf("buffstat: duplicate name %s", n))
			}
			byName[n] = s
		}
	}
}

// Lookup returns the row for a name or alias.
func Lookup(name Stat) (Spec, bool) {
	s, ok := byName[name]
	return s, ok
}

// ByBit returns the row for a bit.
func ByBit(bit int) (Spec, bool) {
	s, ok := byBit[bit]
	return s, ok
}

// All returns every row sorted by bit.
func All() []Spec {
	out := append([]Spec(nil), table...)
	sort.Slice(out, func(i, j int) bool { return out[i].Bit < out[j].Bit })
	return out
}

// Resolve returns the rows for names, failing on an unknown, unsendable or
// repeated stat so a guessed bit can never reach a client.
func Resolve(names []Stat) ([]Spec, error) {
	out := make([]Spec, 0, len(names))
	seen := map[int]bool{}
	for _, n := range names {
		s, ok := byName[n]
		if !ok {
			return nil, fmt.Errorf("buffstat: unknown stat %q", n)
		}
		if !s.LocalSendable() {
			return nil, fmt.Errorf("buffstat: stat %s has no audited native layout", n)
		}
		if seen[s.Bit] {
			return nil, fmt.Errorf("buffstat: stat %s repeated", n)
		}
		seen[s.Bit] = true
		out = append(out, s)
	}
	return out, nil
}

// Mask builds the 8-word mask in wire order (word 0 first).
func Mask(specs []Spec) [MaskWords]uint32 {
	var m [MaskWords]uint32
	for _, s := range specs {
		m[MaskWords-1-s.Bit/32] |= 1 << uint(s.Bit%32)
	}
	return m
}

// IntValues reports whether local triplet values are I32 for this mask.
func IntValues(specs []Spec) bool {
	for _, s := range specs {
		if s.ForcesInt {
			return true
		}
	}
	return false
}

// HasMoveTail reports whether OnTemporaryStatSet reads the movement byte.
func HasMoveTail(specs []Spec) bool {
	for _, s := range specs {
		if s.MoveTail {
			return true
		}
	}
	return false
}

// LocalTriplets returns the stats with a triplet in encodeForLocal order.
func LocalTriplets(specs []Spec) []Spec {
	return sortedBy(specs, func(s Spec) int { return s.Order })
}

// LocalTails returns one representative per TailOrder, in read order.
func LocalTails(specs []Spec) []Spec {
	seen := map[int]bool{}
	var out []Spec
	for _, s := range sortedBy(specs, func(s Spec) int { return s.TailOrder }) {
		if !seen[s.TailOrder] {
			seen[s.TailOrder] = true
			out = append(out, s)
		}
	}
	return out
}

// TwoStates returns the two-state stats in bit order.
func TwoStates(specs []Spec) []Spec {
	return sortedBy(specs, func(s Spec) int {
		if s.TwoState == 0 {
			return 0
		}
		return s.Bit
	})
}

// Indies returns the indie stats in IndieTempStat order.
func Indies(specs []Spec) []Spec { return sortedBy(specs, func(s Spec) int { return s.IndieOrder }) }

// RemoteSorted returns the remotely decoded stats in encodeForRemote order.
func RemoteSorted(specs []Spec) []Spec {
	return sortedBy(specs, func(s Spec) int { return s.RemoteOrder })
}

func sortedBy(specs []Spec, key func(Spec) int) []Spec {
	var out []Spec
	for _, s := range specs {
		if key(s) > 0 {
			out = append(out, s)
		}
	}
	sort.SliceStable(out, func(i, j int) bool { return key(out[i]) < key(out[j]) })
	return out
}
